{
  int32_t ret;

  if (Instance >= SD_INSTANCES_NBR)
  {
    ret = BSP_ERROR_WRONG_PARAM;
  }
  else
  {
    (void)HAL_SD_GetCardInfo(&hsd_sdmmc[Instance], CardInfo);
    ret = BSP_ERROR_NONE;
  }

  /* Return BSP status */
  return ret;
}

