  */
#define TS_MIN(a,b) ((a > b) ? b : a)
/**
  * @}
  */
/** @defgroup STM32H7S78_DK_TS_Private_Function_Prototypes Private Function Prototypes
  * @{
  */
static int32_t GT911_Probe(uint32_t Instance);
static void TS_EXTI_Callback(void);
